<script setup lang="ts">
import {ref,watch} from 'vue'
import type {Row} from '../types'
import UiIcon from '../components/UiIcon.vue'
const props=defineProps<{me:Row,busy:boolean,error:string,token:string}>()
const emit=defineEmits<{generateToken:[],addMember:[body:{username:string,password:string,role:string}]}>()
const memberName=ref(''),memberPassword=ref(''),memberRole=ref('ANALYST'),submitted=ref(false),created=ref(false),copied=ref(false),copyFailed=ref(false)
const roles:Record<string,string>={ADMIN:'管理员',ANALYST:'研究员',REVIEWER:'复核员'}
watch(()=>props.busy,(busy,wasBusy)=>{if(wasBusy&&!busy&&submitted.value){if(!props.error){memberName.value='';memberPassword.value='';created.value=true}submitted.value=false}})
watch(()=>props.token,()=>{copied.value=false;copyFailed.value=false})
function addMember(){submitted.value=true;created.value=false;emit('addMember',{username:memberName.value.trim(),password:memberPassword.value,role:memberRole.value})}
async function copyToken(){try{await navigator.clipboard.writeText(props.token);copied.value=true;copyFailed.value=false}catch{copyFailed.value=true}}
</script>

<template>
  <div class="settings-view">
    <section class="settings-section access-panel" aria-labelledby="api-access-heading">
      <div class="settings-heading"><h2 id="api-access-heading">批处理 API 接入</h2><p>将年度财报核验接入研究流程。</p></div>
      <div class="settings-body"><dl class="token-properties"><div><dt>令牌权限</dt><dd><code>submit</code><span>提交、读取与管理本人任务</span></dd></div><div><dt>有效期</dt><dd>7 天</dd></div><div><dt>人工复核</dt><dd>需使用浏览器会话完成</dd></div></dl><div class="token-actions"><button @click="emit('generateToken')" :disabled="busy"><UiIcon name="plus" :size="15"/>生成 7 天令牌</button><span>请将令牌视为账号凭证保管</span></div><div v-if="token" class="token-result"><div class="token-result-heading"><strong>仅本次显示，请及时保存</strong><button @click="copyToken">{{copied?'已复制':'复制令牌'}}</button></div><code class="token" tabindex="0" aria-label="新生成的 API 令牌">{{token}}</code><p v-if="copyFailed" class="copy-failed" role="status">复制不可用，请选中上方令牌手动复制。</p><p v-else role="status">{{copied?'令牌已复制到剪贴板。':'离开当前会话后，将无法再次查看这枚令牌。'}}</p></div></div>
    </section>
    <section class="settings-section member-panel" aria-labelledby="member-heading">
      <div class="settings-heading"><h2 id="member-heading">组织成员</h2><p>账号及组织内的工作权限。</p></div>
      <div class="settings-body"><div class="current-member"><span class="member-avatar" aria-hidden="true">{{String(me.username||'F').slice(0,1).toUpperCase()}}</span><div><strong>{{me.username}}</strong><span>当前账号</span></div><span class="member-role">{{roles[me.role]||me.role}}</span></div>
      <form v-if="me.role==='ADMIN'" @submit.prevent="addMember" :aria-busy="busy"><h3>新增组织成员</h3><div class="member-fields"><div><label for="member-username">用户名</label><input id="member-username" v-model="memberName" name="member-username" autocomplete="off" required :disabled="busy" spellcheck="false" autocapitalize="none"></div><div><label for="member-password">初始密码</label><input id="member-password" v-model="memberPassword" name="member-password" type="password" autocomplete="new-password" minlength="12" required :disabled="busy" aria-describedby="member-password-hint"><small id="member-password-hint" class="field-hint">至少 12 个字符</small></div><div class="role-field"><label for="member-role">角色</label><select id="member-role" v-model="memberRole" :disabled="busy"><option value="ANALYST">研究员 · 提交与跟踪任务</option><option value="REVIEWER">复核员 · 查看证据与人工复核</option><option value="ADMIN">管理员 · 团队与工作空间管理</option></select></div></div><p v-if="created" class="member-success" role="status"><UiIcon name="check" :size="16"/>成员已创建，初始密码已清空。</p><button class="primary create-member" :disabled="busy">{{busy&&submitted?'正在创建…':'创建成员'}}</button></form>
      <p v-else class="member-permissions"><UiIcon name="lock" :size="14"/><span>成员由组织管理员管理，需要调整时请联系管理员。</span></p></div>
    </section>
  </div>
</template>

<style scoped>
.settings-view{max-width:1060px}.settings-section{display:grid;grid-template-columns:220px minmax(0,1fr);gap:44px;padding:24px 0 30px;border-bottom:1px solid var(--line)}.settings-section:first-child{padding-top:12px}.settings-heading{min-width:0}.settings-heading h2{font-size:0.9375rem;line-height:1.5;font-weight:600;margin:0 0 8px}.settings-heading p{font-size:0.875rem;line-height:1.8;color:var(--muted);margin:0}.settings-body{min-width:0;max-width:640px}.token-properties{padding:0;margin:0}.token-properties>div{display:grid;grid-template-columns:92px minmax(0,1fr);gap:16px;padding:11px 0;border-bottom:1px solid var(--line);font-size:0.9375rem;line-height:1.8}.token-properties>div:first-child{padding-top:0}.token-properties dt{color:var(--muted)}.token-properties dd{margin:0;color:var(--ink)}.token-properties code{padding:2px 6px;border:1px solid var(--line);border-radius:3px;background:var(--canvas);font-size:0.875rem}.token-properties dd>span{margin-left:10px;color:var(--muted);font-size:0.875rem}.token-actions{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-top:18px}.token-actions button{font-size:0.9375rem;min-height:36px;padding:7px 11px}.token-actions>span{font-size:0.875rem;line-height:1.8;color:var(--muted)}.token-result{margin-top:18px;border:1px solid var(--line);border-radius:5px;background:var(--canvas);padding:14px}.token-result-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}.token-result-heading strong{font-size:0.875rem;font-weight:500;line-height:1.7}.token-result-heading button{font-size:0.875rem;padding:5px 8px;min-height:32px;flex-shrink:0}.token{display:block;white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-all;font-family:Consolas,"SFMono-Regular",monospace;font-size:0.9375rem;line-height:1.8;color:var(--ink);padding:10px;background:var(--surface);border:1px solid var(--line);border-radius:4px;user-select:all;margin:0}.token-result>p{font-size:0.875rem;line-height:1.8;color:var(--muted);margin:10px 0 0}.token-result>p.copy-failed{color:var(--warning)}.current-member{display:flex;align-items:center;gap:10px;padding:0 0 18px;min-width:0}.member-avatar{width:32px;height:32px;display:grid;place-items:center;background:var(--canvas);border:1px solid var(--line);border-radius:5px;color:var(--primary);font-size:0.9375rem;font-weight:500;flex-shrink:0}.current-member>div{min-width:0}.current-member strong{font-size:0.9375rem;line-height:1.6;font-weight:500;display:block;overflow-wrap:anywhere}.current-member>div>span{font-size:0.875rem;line-height:1.6;color:var(--muted)}.member-role{margin-left:auto;font-size:0.875rem;color:var(--muted);flex-shrink:0}.member-panel form{padding-top:18px;border-top:1px solid var(--line)}.member-panel h3{font-size:0.9375rem;font-weight:600;margin:0 0 16px}.member-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.member-fields>div{min-width:0}.role-field{grid-column:1/-1;max-width:360px}.member-panel label{display:block;margin:0 0 6px;font-size:0.875rem;font-weight:500;line-height:1.7}.member-panel input,.member-panel select{height:38px;padding:8px 10px;border:1px solid #cdd1cb;border-radius:5px;background:var(--surface);color:var(--ink);width:100%;min-width:0;font-size:0.9375rem}.field-hint{display:block;font-size:0.875rem;line-height:1.8;color:var(--muted);margin-top:5px}.create-member{margin-top:20px;font-size:0.9375rem;min-height:36px;padding:7px 14px}.member-success{display:flex;align-items:center;gap:7px;font-size:0.875rem;line-height:1.8;color:var(--success);margin:16px 0 0}.member-permissions{display:flex;align-items:flex-start;gap:8px;font-size:0.875rem;line-height:1.9;color:var(--muted);margin:0;padding-top:14px;border-top:1px solid var(--line)}.member-permissions>svg{margin-top:4px;flex-shrink:0}
@media(max-width:1050px){.settings-section{grid-template-columns:170px minmax(0,1fr);gap:28px}.token-properties dd>span{display:block;margin:4px 0 0}}
@media(max-width:899px){.settings-section{grid-template-columns:minmax(0,1fr);gap:20px;padding:24px 0}.settings-body{max-width:none}.settings-heading p{margin-top:3px}.settings-heading h2{margin-bottom:0}}
@media(max-width:767px){.member-fields{grid-template-columns:minmax(0,1fr);gap:16px}.role-field{max-width:none}.member-panel input,.member-panel select{height:44px;font-size:1rem}.token-actions button,.token-result-heading button,.create-member{min-height:44px}.token-properties>div{grid-template-columns:78px minmax(0,1fr);gap:12px}.token-result{padding:12px}.token-result-heading{gap:8px}.token{font-size:0.9375rem}}
.member-panel input,.member-panel select { height: auto; min-height: 42px; line-height: 1.5; }
@media (max-width: 767px) { .member-panel input,.member-panel select { min-height: 44px; } }
</style>
